// This file is generated by AI.

// 场景文件/文件夹操作: 新建、重命名、删除。
//
// 磁盘操作成功后, 同步迁移/关闭已打开的场景选项卡、Monaco model 与 LSP 状态 ——
// 否则会出现"文件已经改名, 选项卡还指着旧路径"这类不一致。
//
// 与框架无关: 只经 store 门面读写状态。

import { copyDirectory, moveToTrash } from './commands/server';
import { fs } from './lib/fs';
import { toUri } from './lib/uri';
import { lspClient } from './lsp/client';
import { disposeModel } from './lsp/monaco';
import { useAppStore } from './state/store.svelte';
import { sceneTabId } from './tabs/model';

/** 校验文件/文件夹名称, 返回错误信息或 null。 */
export function validateName(name: string): string | null {
  const trimmed = name.trim();
  if (!trimmed) return '名称不能为空';
  if (trimmed === '.' || trimmed === '..') return '名称无效';
  if (/[\\/:*?"<>|]/.test(trimmed)) return '名称不能包含 \\ / : * ? " < > | 字符';
  return null;
}

/**
 * 名称补扩展名。
 *
 * 场景文件按 WebGAL 约定是 `.txt`; 名称里已经带点就原样保留 (用户可以显式写别的后缀)。
 */
export function ensureExtension(name: string, extension: string): string {
  const trimmed = name.trim();
  return trimmed.includes('.') ? trimmed : `${trimmed}.${extension}`;
}

/** 新建空文件, 返回完整路径。 */
export async function createFile(dirPath: string, name: string, extension = 'txt'): Promise<string> {
  const full = `${dirPath.replace(/[\\/]+$/, '')}\\${ensureExtension(name, extension)}`;
  await fs.writeText(full, '');
  return full;
}

/** 新建文件夹, 返回完整路径。 */
export async function createFolder(dirPath: string, name: string): Promise<string> {
  const full = `${dirPath.replace(/[\\/]+$/, '')}\\${name.trim()}`;
  await fs.mkdir(full);
  return full;
}

/** 项目内的相对路径 (正斜杠)。 */
export function projectRelativePath(projectPath: string, filePath: string): string {
  const base = projectPath.replace(/[\\/]+$/, '').replace(/\\/g, '/');
  const abs = filePath.replace(/\\/g, '/');
  if (abs === base) return '.';
  if (abs.toLowerCase().startsWith(`${base.toLowerCase()}/`)) return abs.slice(base.length + 1);
  return abs;
}

/**
 * 浏览器菜单里"复制路径"的取值: 场景去掉 `game/scene/`, 资源去掉 `game/` 与可省略的第一级
 * 目录 —— 复制出来的是用户写脚本时真正要填的那个相对路径, 而不是磁盘上的完整位置。
 */
export function browserRelativePath(projectPath: string, filePath: string): string {
  const relative = projectRelativePath(projectPath, filePath).replace(/^\/+/, '');
  const scenePrefix = 'game/scene/';
  if (relative.toLowerCase().startsWith(scenePrefix)) return relative.slice(scenePrefix.length);

  const gamePrefix = 'game/';
  if (!relative.toLowerCase().startsWith(gamePrefix)) return relative;
  const resourcePath = relative.slice(gamePrefix.length);
  const segments = resourcePath.split('/');
  return segments.length > 1 ? segments.slice(1).join('/') : resourcePath;
}

/** 在目录里找一个不冲突的目标路径 (加了 ` (1)`、` (2)` 这类后缀)。 */
export async function uniqueTargetPath(dirPath: string, name: string): Promise<string> {
  const dir = dirPath.replace(/[\\/]+$/, '');
  const dot = name.lastIndexOf('.');
  const stem = dot > 0 ? name.slice(0, dot) : name;
  const ext = dot > 0 ? name.slice(dot) : '';

  let candidate = `${dir}\\${name}`;
  let index = 1;
  // 存在性必须问磁盘: 只做本地命名去重的话, "复制到同目录"会覆盖自己
  while ((await fs.exists(candidate)).exists) {
    candidate = `${dir}\\${stem} (${index})${ext}`;
    index += 1;
  }
  return candidate;
}

/** 把文件/目录复制到目标目录 (同名时自动改名), 返回新路径。 */
export async function copyEntryToDirectory(sourcePath: string, targetDir: string): Promise<string> {
  const name = sourcePath.split(/[\\/]/).pop() ?? 'item';
  const info = await fs.exists(sourcePath);
  const dest = await uniqueTargetPath(targetDir, name);

  if (info.isDirectory) await copyDirectory(sourcePath, dest);
  else await fs.copyFile(sourcePath, dest);
  return dest;
}

/**
 * 让用户挑若干个文件复制进某个目录 —— 两个浏览器里「添加资源」这一项的动作。
 *
 * 语义是**导入已有的文件/图片/音频** (从别处拷素材进来), 而不是新建一个空文件: 多选对话框
 * → 逐个 `copyEntryToDirectory` (重名自动改名)。返回实际写入的新路径列表, 调用方据此刷新目录。
 */
export async function importFilesToDir(dirPath: string): Promise<string[]> {
  const { open } = await import('@tauri-apps/plugin-dialog');
  const picked = await open({ multiple: true, title: '添加资源', directory: false });
  if (!picked) return [];

  const sources = Array.isArray(picked) ? picked : [picked];
  const created: string[] = [];
  for (const source of sources) created.push(await copyEntryToDirectory(source, dirPath));
  return created;
}

/**
 * 把"项目内的相对路径"复制到剪贴板 —— 两个浏览器的「复制相对路径」共用这一处: "相对路径怎么算"
 * 只有一个口径 (`browserRelativePath`), 剪贴板被拒 (窗口无焦点 / 无权限) 时静默。
 */
export async function copyRelativePathToClipboard(projectPath: string, filePath: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(browserRelativePath(projectPath, filePath));
  } catch {
    // 剪贴板不可用时静默: 这只是个便利动作, 弹框反而更烦
  }
}

/** 重命名文件/文件夹, 并把受影响的已打开文档迁移到新路径 (含 LSP / Monaco model / 诊断)。 */
export async function renamePath(oldPath: string, newPath: string): Promise<void> {
  await fs.rename(oldPath, newPath); // 磁盘失败则直接抛出, 不迁移内存状态

  const store = useAppStore.getState();
  const oldNorm = oldPath.replace(/\\/g, '/').toLowerCase();
  for (const doc of [...store.documents]) {
    const normalized = doc.path.replace(/\\/g, '/').toLowerCase();
    if (normalized !== oldNorm && !normalized.startsWith(`${oldNorm}/`)) continue;
    // 目录重命名时, 子文件路径追加原相对部分 (按实际大小写切片)
    const suffix = doc.path.replace(/\\/g, '/').slice(oldPath.replace(/\\/g, '/').length);
    const newDocPath = `${newPath.replace(/\\/g, '/')}${suffix}`.replace(/\//g, '\\');
    disposeModel(doc.path);
    lspClient.closeDocument(doc.path);
    store.updateDocument(doc.path, {
      path: newDocPath,
      name: newDocPath.split(/[\\/]/).pop() ?? newDocPath,
      uri: toUri(newDocPath),
      isScene: newDocPath.replace(/\\/g, '/').includes('/game/scene/'),
    });
    // 选项卡按路径索引, 需同步迁移 (保持原位置与顺序)
    store.retargetSceneTabs(doc.path, newDocPath);
  }

  /*
   * 诊断同样按路径存放, 也要跟着挪。
   *
   * 不挪的话项目诊断列表里会留下指向旧路径的条目 —— 语言服务只为**新**路径推诊断, 旧路径
   * 那一条永远等不到更新, 于是"改好了"的问题一直挂在列表上, 点它还跳不过去。
   */
  store.retargetDiagnostics(oldPath, newPath);
}

/** 删除文件/文件夹 (移动至系统回收站), 并关闭受影响的已打开选项卡。 */
export async function deletePath(path: string): Promise<void> {
  await moveToTrash(path); // 磁盘失败则直接抛出, 不关闭选项卡

  const store = useAppStore.getState();
  const norm = path.replace(/\\/g, '/').toLowerCase();
  for (const doc of [...store.documents]) {
    const normalized = doc.path.replace(/\\/g, '/').toLowerCase();
    if (normalized !== norm && !normalized.startsWith(`${norm}/`)) continue;
    disposeModel(doc.path);
    lspClient.closeDocument(doc.path);
    store.closeDocument(doc.path);
    store.closeTab(sceneTabId(doc.path));
  }
  // 磁盘上已经没有这个文件了, 语言服务不会再为它推诊断 —— 不清就是列表里的幽灵条目
  store.clearDiagnostics(path);
}
